--PARA SACAR MES EJEMPLO

SELECT  
DATENAME(MONTH, DATEADD(MONTH,MONTH(T.FECHA) - 1, '1900-01-01')) AS MESLETRA,
T.FECHA,
YEAR(T.FECHA) AS AÑO,
MONTH(T.FECHA) AS MES,
T.BRUTO,
V.NOMBRE,
T.NRODCTO,
M.DESCRIPCIO
FROM
TRADE AS T, 
VENDEN AS V,
TIPOVTA AS M
WHERE 
T.CODVEN ='07' AND
--T.BRUTO >'0' AND
T.CODVEN = V.CODVEN AND
T.TIPODCTO IN('NC','FA') AND
T.ORIGEN ='FAC' AND
M.TIPOVTA= T.TIPOVTA AND 
T.TIPOVTA IN ('0-020','0-025','16','28')AND
T.TIPODCTO Not In ('P1','P2','P3','RE','AN','CD','06','13','PD','03','04','05','07','08','09','10','11','12','14','15','16','17','18','19','20','21','AJ','EP','CT','OP','OR','OF','OT','OM','CP') AND
--T.nota not like '%anula%' AND 
T.FECHA>'01/01/2019' And T.FECHA<='31/12/2023' 
GROUP BY T.FECHA,T.BRUTO,V.NOMBRE,T.NRODCTO,M.DESCRIPCIO ORDER BY T.FECHA ASC;

