---query sacar data producto terminado con rango de fecha de 2 años
SELECT     A.BODEGA, B.CODGRUPO, C.NOMBRE, A.CODIGO,B.CODBARRAS, B.DESCRIPCIO, A.NIT,  D.NOMBRE,  B.FECHA_ING, E.CODIGO
FROM         SALDOINV A INNER JOIN
                      MTMERCIA B ON A.CODIGO = B.CODIGO INNER JOIN
                      MTGRUINV C ON B.CODGRUPO = C.CODGRUPO INNER JOIN
                      MTPROCLI D ON A.NIT = D.NIT	INNER JOIN
					  TIPOINV E  ON B.TIPOINV =  E.CODIGO
WHERE  (E.CODIGO LIKE ('%PT%'))  
and YEAR (b.FECHA_ING) > = YEAR (GETDATE())  - 2
GROUP BY A.BODEGA, B.CODGRUPO, C.NOMBRE, A.CODIGO, B.CODBARRAS, B.DESCRIPCIO, A.NIT, D.NOMBRE,  B.FECHA_ING, E.CODIGO 
ORDER BY C.NOMBRE, B.DESCRIPCIO, B.FECHA_ING
---query sacar data producto terminado con rango de fecha de 2 años
SELECT A.CODIGO, A.CODBARRAS ,A.DESCRIPCIO, A.TIPOINV, B.NOMBRE AS TIPOINVENTARIO, F.NOMBRE AS SUBINVENTARIO, A.CODLINEA, C.NOMBRE AS TIPOLINEA, 
E.NOMBRE AS TIPOGRUPO, A.FECING, G.NOMBRE AS CLASIFICACION1, D.NOMBRE AS CLASIFICACION2
FROM MTMERCIA A, TIPOINV B, MTLINEA C, MTGRUINV E, MTSBLIN F, MT1CLAF G, MT2CLAF D
WHERE   (B.CODIGO IN ('PT005','PT010','PT015','PT020','PT025','PT030','PT035','PT036','PT037','PT038','PT039','PT040','PT045'))
AND YEAR (A.FECING) > = YEAR (GETDATE())  - 2
AND A.TIPOINV = B.CODIGO
AND A.CODLINEA = C.CODLINEA
AND A.CODGRUPO = E.CODGRUPO
AND A.CODSBLIN = F.CODSBLIN
AND A.CLASIFICA1 = G.CODIGO
AND A.CLASIFICA2 = D.CODIGO

