-----query saldos y reservas suministros
select B.BODEGA,A.CODIGO,A.DESCRIPCIO,A.UNIDADMED,B.CODLOTE,B.CODUBICA,
SUM(B.ICANTIDAD) - SUM(B.OCANTIDAD) AS SALDO,
SUM(B.RESERVA) AS RESERVA
from mtmercia A INNER JOIN 
	 SALDOINV B ON A.CODIGO=B.CODIGO AND B.BODEGA='12.SUMINIS' 
where  B.BODEGA='12.SUMINIS' 
GROUP BY B.BODEGA,A.CODIGO,A.DESCRIPCIO,A.UNIDADMED,B.CODLOTE,B.CODUBICA
HAVING SUM(B.ICANTIDAD) - SUM(B.OCANTIDAD) > 0

SELECT *
FROM MTMERCIA MERCIA 

SELECT M.CODIGO, M.DESCRIPCIO, M.COSTO_ING,P.PRECIO,P.PRECIOSTD
FROM MTMERCIA AS M, MVPRECIO AS P
WHERE  M.CODIGO= P.CODPRODUC
AND P.CODPRECIO='01'
AND P.PRECIO >'0'
--AND  MERCIA.CODIGO='03149'
GROUP BY M.CODIGO, M.DESCRIPCIO, M.COSTO_ING,P.PRECIO,P.PRECIOSTD ORDER BY M.DESCRIPCIO

