SELECT        YEAR(FECHA) AS Expr1, TIPODCTO, NRODCTO, FECHA
FROM            TRADE
WHERE        (FECHA >= '01/01/2022') AND (FECHA <= '31/12/2023')
ORDER BY TIPODCTO, NRODCTO

SELECT        YEAR(FECHA) AS Expr1, TIPODCTO, NRODCTO, FECHA, ORIGEN, TIPOMVTO
FROM            TRADE
WHERE        (NRODCTO IN ('3319', '3320', '3321', '3322', '3323', '3324', '3325', '3326', '3327', '3328', '3329', '3330', '3331')) AND (FECHA >= '01/01/2008') AND (FECHA <= '31/12/2022')
ORDER BY Expr1, TIPODCTO, NRODCTO

